    PUT /vertex
    {
       "label": "person",
       "creationDate": 1713862800,
       "properties": [
         {
           "propertyId": "name",
           "propertyValue": "John Doe",
           "fullQualifiedTypeName": "System.String"
         }
       ]
    }

